#[cfg(test)]mod consulta_recovery_tests{
 use super::*;
 #[test]fn limites_busqueda_sin_ampliacion(){for q in [""," ","uno dos tres cuatro cinco seis siete ocho nueve",&"x".repeat(201)]{let v=json!({"name":"buscar_documentos","arguments":{"consulta":q,"limite":3}});assert_eq!(validate_call(&v).unwrap_err().downcast_ref::<crate::recovery::ItemFault>().unwrap().0,crate::recovery::ItemCode::SearchQueryBounds);}for q in ["uno dos tres cuatro cinco seis siete ocho",&"x".repeat(200)]{assert!(validate_call(&json!({"name":"buscar_documentos","arguments":{"consulta":q,"limite":3}})).is_ok())}}
 #[test]fn p22_sse_original_por_http_sin_vencimiento(){
 use std::net::TcpListener;let source=Path::new(crate::consulta_recovery::P22);let payload=fs::read(source.join("01-GENERACION-ORIGINAL.sse")).unwrap();let body=payload.clone();let listener=TcpListener::bind("127.0.0.1:1234").unwrap();let server=std::thread::spawn(move||{let(mut s,_)=listener.accept().unwrap();s.set_read_timeout(Some(Duration::from_secs(10))).unwrap();let mut input=BufReader::new(s.try_clone().unwrap());let mut n=0;loop{let mut line=String::new();input.read_line(&mut line).unwrap();if line=="\r\n"{break}if let Some((k,v))=line.split_once(':'){if k.eq_ignore_ascii_case("content-length"){n=v.trim().parse::<usize>().unwrap()}}}let mut req=vec![0;n];input.read_exact(&mut req).unwrap();write!(s,"HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",body.len()).unwrap();s.write_all(&body).unwrap();});let root=std::env::temp_dir().join(store::id("replay-p22"));fs::create_dir(&root).unwrap();let client=reqwest::blocking::Client::builder().no_proxy().build().unwrap();let e=generate(&client,&json!({}),&root,"01-GENERACION",None).unwrap_err();server.join().unwrap();assert_eq!(e.downcast_ref::<crate::recovery::ItemFault>().unwrap().0,crate::recovery::ItemCode::SearchQueryBounds);assert_eq!(fs::read(root.join("01-GENERACION-ORIGINAL.sse")).unwrap(),payload);assert_eq!(fs::read(root.join("01-GENERACION-EMISION.bin")).unwrap(),fs::read(source.join("01-GENERACION-EMISION.bin")).unwrap());assert!(!root.join("mcp").exists());assert!(!root.join("FINAL.json").exists());fs::remove_dir_all(root).unwrap();
 }
}
